using Captovix;
int passed=0;
void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);passed++;Console.WriteLine("PASS: "+name);}
void Reject(Action action,string name){try{action();}catch(InvalidDataException){Check(true,name);return;}throw new Exception("FAIL accepted: "+name);}
EditorDocument Doc()=>new(){OriginalWidth=800,OriginalHeight=600,SourceHash="hash"};
Annotation Rect(double x,double y,double w=30,double h=30)=>new(){Kind=AnnotationKind.Rectangle,X1=x,Y1=y,X2=x+w,Y2=y+h};
AnnotationBox Box(Annotation a)=>new(a.Left,a.Top,Math.Max(1,a.Width),Math.Max(1,a.Height));
void Validate(EditorDocument d)=>d.Validate(800,600,"hash");
foreach(int version in new[]{1,2,3}){var legacy=Doc();legacy.Version=version;legacy.Annotations.Add(Rect(10,20));var id=legacy.Annotations[0].Id;Validate(legacy);Check(legacy.Version==11&&legacy.Annotations[0].Id==id&&legacy.Annotations[0].X1==10,"Migrate supported schema "+version);}
var stroke=new Annotation{Kind=AnnotationKind.Freehand};stroke.AddPoint(10,20);stroke.AddPoint(90,10);stroke.AddPoint(45,80);
var d=Doc();d.Annotations.Add(stroke);Validate(d);var clone=EditorDocument.Deserialize(d.Serialize());Validate(clone);
Check(clone.Annotations[0].Points.SequenceEqual(stroke.Points),"Freehand roundtrip preserves every point");
var copy=stroke.Copy();copy.Points[0]=new(0,0);Check(stroke.Points[0]==new AnnotationPoint(10,20),"Copies do not share mutable point arrays");
copy=stroke.Copy();copy.Translate(12,14);Check(copy.Points[0]==new AnnotationPoint(22,34)&&copy.X1==22&&copy.Y1==24,"Move translates stroke geometry and bounds together");
copy=stroke.Copy();AnnotationEditing.Transform(copy,stroke,new(10,10,80,70),new(100,100,160,140));
Check(copy.Points[0]==new AnnotationPoint(100,120)&&copy.Points[1]==new AnnotationPoint(260,100)&&stroke.Points[0].X==10,"Resize transforms freehand points without mutating snapshot");
var callout=new Annotation{Kind=AnnotationKind.Callout,X1=40,Y1=50,X2=180,Y2=130,TailX=20,TailY=150,Text="Ghi chú\nTiếng Việt"};
d.Annotations.Add(callout);Validate(d);clone=EditorDocument.Deserialize(d.Serialize());Validate(clone);
Check(clone.Annotations[1].Text==callout.Text&&clone.Annotations[1].TailY==150,"Callout roundtrip keeps text, body and tail");
copy=callout.Copy();copy.Translate(10,20);Check(copy.TailX==30&&copy.TailY==170&&copy.X1==50,"Callout movement keeps pointer attached");
AnnotationEditing.Transform(copy,callout,new(20,50,160,100),new(40,100,320,200));
Check(copy.TailX==40&&copy.TailY==300&&copy.X1==80&&copy.FontSize==callout.FontSize,"Callout resize transforms its pointer and retains chosen font size");
AnnotationEditing.Transform(copy,callout,new(20,50,160,100),new(40,100,2,2));Check(copy.Width>=36&&copy.Height>=36,"Callout resize cannot create an unsaveable tiny body");
var bad=Doc();bad.Annotations.Add(new(){Kind=AnnotationKind.Freehand});Reject(()=>Validate(bad),"Empty persisted stroke rejected");
bad=Doc();var invalidStroke=stroke.Copy();invalidStroke.Points[0]=new(double.NaN,0);bad.Annotations.Add(invalidStroke);Reject(()=>Validate(bad),"Nonfinite stroke point rejected");
bad=Doc();bad.Annotations.Add(Rect(1,1));bad.Annotations[0].Points.Add(new(1,1));Reject(()=>Validate(bad),"Hidden points on non-freehand objects rejected");
bad=Doc();copy=callout.Copy();copy.TailX=double.PositiveInfinity;bad.Annotations.Add(copy);Reject(()=>Validate(bad),"Nonfinite callout pointer rejected");
bad=Doc();copy=callout.Copy();copy.X2=copy.X1+2;bad.Annotations.Add(copy);Reject(()=>Validate(bad),"Tiny persisted callout rejected");
bad=Doc();copy=stroke.Copy();copy.Points=Enumerable.Repeat(new AnnotationPoint(1,1),Annotation.MaxPoints+1).ToList();bad.Annotations.Add(copy);Reject(()=>Validate(bad),"Oversized persisted stroke rejected");
bad=Doc();var capped=new Annotation{Kind=AnnotationKind.Freehand};for(int i=0;i<Annotation.MaxPoints+10;i++)capped.AddPoint(i,0);Check(capped.Points.Count==Annotation.MaxPoints,"Live stroke sampling has a hard cap");
bad.Annotations.Add(Rect(1,1));bad.Annotations[0].GroupId="invalid";Reject(()=>Validate(bad),"Malformed persisted group identity rejected");
d=Doc();var a=Rect(10,10);var b=Rect(60,20);var c=Rect(150,50);d.Annotations.AddRange([a,b,c]);
var group=AnnotationEditing.Group(d,[a.Id,b.Id]);Check(group!=null&&a.GroupId==b.GroupId&&c.GroupId==null,"Grouping changes only selected membership");
Check(AnnotationEditing.ExpandGroups(d,[a.Id]).SetEquals([a.Id,b.Id]),"Selecting one member expands the entire group");
Check(AnnotationEditing.Units(d,[a.Id,c.Id]).Length==2,"A group counts as one layout unit");
var deltaX=b.X1-a.X1;AnnotationEditing.Align(d,[a.Id,c.Id],AnnotationAlignment.Left,Box);
Check(a.X1==c.X1&&b.X1-a.X1==deltaX,"Alignment moves a group without collapsing its members");
var copies=AnnotationEditing.Duplicate(d,[a.Id],Box);var duplicated=d.Annotations.Where(x=>copies.Contains(x.Id)).ToArray();
Check(duplicated.Length==2&&duplicated.Select(x=>x.Id).Distinct().Count()==2,"Duplicate expands groups and generates unique object IDs");
Check(duplicated[0].GroupId==duplicated[1].GroupId&&duplicated[0].GroupId!=group,"Duplicate group has an independent identity");
Check(duplicated[0].X1==a.X1+16&&duplicated[0].Y1==a.Y1+16,"Duplicate applies a predictable in-image offset");
AnnotationEditing.Ungroup(d,[a.Id]);Check(a.GroupId==null&&b.GroupId==null&&duplicated[0].GroupId!=null,"Ungroup expands only the original group");
var merged=AnnotationEditing.Group(d,[duplicated[0].Id,c.Id]);Check(duplicated.All(x=>x.GroupId==merged)&&c.GroupId==merged,"Grouping existing groups is flat and retains every member");
d=Doc();var p1=Rect(10,10,20,20);var p2=Rect(35,40,40,20);var p3=Rect(200,180,30,40);d.Annotations.AddRange([p1,p2,p3]);
Check(AnnotationEditing.Distribute(d,d.Annotations.Select(x=>x.Id),true,Box),"Horizontal distribution accepts three independent units");
Check(Math.Abs((p2.Left-p1.X2)-(p3.Left-p2.X2))<.0001&&p1.X1==10&&p3.X1==200,"Horizontal distribution equalizes gaps and fixes endpoints");
Check(AnnotationEditing.Distribute(d,d.Annotations.Select(x=>x.Id),false,Box),"Vertical distribution accepts unequal object sizes");
Check(Math.Abs((p2.Top-p1.Y2)-(p3.Top-p2.Y2))<.0001&&p1.Y1==10&&p3.Y1==180,"Vertical distribution equalizes gaps and fixes endpoints");
var before=d.Serialize();Check(!AnnotationEditing.Distribute(d,[p1.Id,p2.Id],true,Box)&&d.Serialize()==before,"Too few layout units leaves the document untouched");
d=Doc();a=Rect(10,10,100);b=Rect(20,10,100);c=Rect(30,10,100);d.Annotations.AddRange([a,b,c]);before=d.Serialize();Check(!AnnotationEditing.Distribute(d,[a.Id,b.Id,c.Id],true,Box)&&before==d.Serialize(),"Insufficient spacing does not move any objects");
d=Doc();a=Rect(10,10);b=Rect(60,10);c=Rect(150,10);var last=Rect(350,10);d.Annotations.AddRange([a,b,c,last]);AnnotationEditing.Group(d,[a.Id,b.Id]);deltaX=b.X1-a.X1;
Check(AnnotationEditing.Distribute(d,[a.Id,c.Id,last.Id],true,Box)&&b.X1-a.X1==deltaX,"Distribution keeps the internal spacing of groups");
d=Doc();a=Rect(0,0);b=Rect(40,0);c=Rect(80,0);d.Annotations.AddRange([a,b,c]);
AnnotationEditing.Reorder(d,[a.Id],AnnotationOrder.Forward);Check(d.Annotations.Select(x=>x.Id).SequenceEqual([b.Id,a.Id,c.Id]),"Move forward crosses one adjacent object");
AnnotationEditing.Reorder(d,[a.Id],AnnotationOrder.Front);Check(d.Annotations[^1].Id==a.Id,"Bring to front places the object last in draw order");
AnnotationEditing.Reorder(d,[a.Id],AnnotationOrder.Back);Check(d.Annotations[0].Id==a.Id,"Send to back places the object first");
AnnotationEditing.Reorder(d,[c.Id],AnnotationOrder.Backward);Check(d.Annotations.Select(x=>x.Id).SequenceEqual([a.Id,c.Id,b.Id]),"Move backward crosses one adjacent object");
AnnotationEditing.Reorder(d,[a.Id,c.Id],AnnotationOrder.Front);Check(d.Annotations.Select(x=>x.Id).SequenceEqual([b.Id,a.Id,c.Id]),"Reorder preserves relative order inside multi-selection");
var cover=new Annotation{Kind=AnnotationKind.Cover};var blur=new Annotation{Kind=AnnotationKind.Blur};d.Annotations.AddRange([cover,blur]);AnnotationEditing.Reorder(d,[a.Id,cover.Id],AnnotationOrder.Back);
Check(d.Annotations.Take(3).All(x=>!x.IsRedaction)&&d.Annotations[^2].Kind==AnnotationKind.Blur&&d.Annotations[^1].Kind==AnnotationKind.Cover,"Layer commands cannot place normal overlays above privacy masks");
var session=new EditorSession(d);before=session.Document.Serialize();session.Change(x=>AnnotationEditing.Group(x,[a.Id,b.Id]));var grouped=session.Document.Serialize();session.Undo();Check(session.Document.Serialize()==before,"Grouping undoes as one complete action");session.Redo();Check(session.Document.Serialize()==grouped,"Redo restores group membership exactly");
session.Change(x=>AnnotationEditing.Duplicate(x,[a.Id],Box));var dup=session.Document.Serialize();session.Undo();Check(session.Document.Serialize()==grouped,"Duplicate group is one undo action");session.Redo();Check(session.Document.Serialize()==dup,"Redo retains duplicate IDs and group identities");
before=session.Document.Serialize();session.Change(x=>AnnotationEditing.Reorder(x,[a.Id],AnnotationOrder.Front));session.Undo();Check(session.Document.Serialize()==before,"Layer movement is fully undoable");
Validate(session.Document);clone=EditorDocument.Deserialize(session.Document.Serialize());Validate(clone);Check(clone.Serialize()==session.Document.Serialize(),"Reopen preserves layer order, groups and object identities");
var bounded=new EditorSession(Doc(),2048);bounded.Change(x=>x.Annotations.Add(new(){Kind=AnnotationKind.Text,Text=new string('x',1800)}));
for(int i=0;i<8;i++)bounded.Change(x=>x.Annotations[0].Text=new string((char)('a'+i),1800));
bounded.Undo();Check(bounded.Document.Annotations[0].Text[0]=='g'&&!bounded.CanUndo,"Large annotation history evicts older snapshots but retains the latest undo");
bounded.Redo();Check(bounded.Document.Annotations[0].Text[0]=='h',"Memory-bounded history retains a matching redo");
Console.WriteLine($"{passed} advanced annotation checks passed.");
